          title: "合一与前向推理的最小实现",
          code: "# 一阶逻辑的合一（unification）与前向推理（forward chaining）最小实现\n# 纯标准语法，不依赖任何库。为便于阅读做了简化：单字母小写视为变量，不做出现检查\n\ndef bind(v, t, theta):\n    if v in theta:\n        return unify(theta[v], t, theta)      # 变量已有绑定，先展开再合一\n        return dict(theta, **{v: t})\n\n        def unify(x, y, theta):\n            # theta 是替换表 {变量: 项}；成功返回新替换表，失败返回 None\n            if theta is None:\n                return None\n                if x == y:\n                    return theta\n                    if isinstance(x, str) and len(x) == 1 and x.islower():\n                        return bind(x, y, theta)\n                        if isinstance(y, str) and len(y) == 1 and y.islower():\n                            return bind(y, x, theta)\n                            if isinstance(x, list) and isinstance(y, list) and len(x) == len(y):\n                                for a, b in zip(x, y):\n                                    theta = unify(a, b, theta)\n                                    if theta is None:\n                                        return None\n                                        return theta\n                                        return None                                # 谓词名或常量不匹配\n\n                                        # 规则：parent(x, y) 且 male(x) => father(x, y)\n                                        RULES = [([['parent', 'x', 'y'], ['male', 'x']], ['father', 'x', 'y'])]\n                                        FACTS = [['parent', 'tom', 'bob'], ['male', 'tom']]\n\n                                        def forward_chain(facts, rules):\n                                            known = [list(f) for f in facts]\n                                            changed = True\n                                            while changed:                             # 一直扫到不再新增事实（求最小不动点）\n                                                changed = False\n                                                for body, head in rules:\n                                                    theta = {}\n                                                    for lit in body:\n                                                        hit = None\n                                                        for f in known:\n                                                            t2 = unify(lit, f, theta)\n                                                            if t2 is not None:\n                                                                hit = t2\n                                                                break\n                                                                theta = hit\n                                                                if theta is None:\n                                                                    break                      # 该规则前提不满足，换下一条规则\n                                                                    if theta is not None:\n                                                                        new = [theta.get(s, s) for s in head]\n                                                                        if new not in known:\n                                                                            known.append(new)\n                                                                            changed = True\n                                                                            return known\n\n                                                                            print(forward_chain(FACTS, RULES))\n                                                                            # 输出含 ['father', 'tom', 'bob']：前向推理从事实出发自动推出新结论"
